/bin/bash -lc "node --input-type=module <<'NODE'
const base = 'http://localhost:3000'
for (const id of ['1', '11']) {
  const res = await fetch("'`${base}/blog/${id}`)
  const html = await res.text()
  const comments = (html.match(/class="comment"/g) || []).length
  const ok = res.status === 200 && comments === 5 && html.includes('"'<title>')
  console.log("'`${ok ? '"'PASS' : 'FAIL'} /blog/"'${id}: status ${res.status}, comments ${comments}`)
  if (!ok) process.exitCode = 1
}
NODE'
